int expectedRgb = sourceImage.getRGB(0, 0);
int actualRgb = destImage.getRGB(0, 0);
assert expectedRgb == actualRgb : "Pixel at (0,0) should match destination origin";

int outsideRgb = destImage.getRGB(srcWidth + 5, srcHeight + 5);
